/**
 * Demo content, for local development only.
 *
 *   npm run db:seed:demo
 *
 * ## Why this exists
 *
 * A design-reference library is images, and an empty one tells you nothing
 * about whether the grid works, whether the filters are useful, or whether a
 * detail page reads well. Capturing real sites to find out is slow and puts
 * other people's material into a demo. So this creates a plausible library:
 * six fictional products, twenty-odd records, two flows, two collections, and
 * real PNG screenshots generated by `screenshots.ts`.
 *
 * ## What is fictional and why that matters
 *
 * Every product here is invented and every URL is under `example.com`. The
 * screenshots depict nothing real. That is deliberate: seeding fabricated
 * screenshots attributed to real companies would put invented material into
 * the system as though it were a record of someone's actual product, and the
 * whole point of the provenance columns is that they are true.
 *
 * ## Where it takes a shortcut, and where it does not
 *
 * It writes content rows directly at their final state rather than walking
 * each one through discover → capture → review → publish. That is a shortcut,
 * and an acceptable one: every row still has to satisfy the same CHECK
 * constraints as a real record — `content_items_publishable` and
 * `content_items_approval_attributable` mean a published row here carries a
 * title, a slug, a published timestamp, a non-blocking rights status and a
 * named approver, exactly as one that came through the queue would.
 *
 * It does **not** shortcut media. Every screenshot goes through `ingestMedia`,
 * so it is sniffed, validated, hashed, dHashed and thumbnailed by the real
 * pipeline. Rendering is deterministic, so re-running deduplicates against
 * what is already stored instead of accumulating copies.
 *
 * §37: "No fake production data in production logic. Use seed data only for
 * local development." This refuses to run with NODE_ENV=production.
 */
import { and, eq, inArray, isNull, sql } from "drizzle-orm";
import {
  type Database,
  collectionItems,
  collections,
  contentItems,
  createDatabase,
  experienceDetails,
  flowDetails,
  flowSteps,
  mediaUsages,
  pageDetails,
  screenDetails,
  sources,
  taxonomyAssignments,
  taxonomyTerms,
  urlRegistry,
  users,
} from "@uxd/database";
import { attachMedia, ingestMedia } from "@uxd/api";
import { createStorage } from "@uxd/media";
import { createHeuristicProvider } from "@uxd/classification";
import {
  createLogger,
  normalizeUrl,
  registrableDomain,
  slugify,
  urlHash,
  uuidv7,
} from "@uxd/shared";
import { loadCmsEnv, loadEnvFile } from "@uxd/shared/env";
import { type Layout, renderScreenshot } from "./screenshots.js";

loadEnvFile();

const logger = createLogger({
  service: "db-seed-demo",
  level: (process.env.UXD_LOG_LEVEL as "info") ?? "info",
  format: process.env.UXD_LOG_FORMAT === "json" ? "json" : "pretty",
});

if (process.env.NODE_ENV === "production") {
  logger.error(
    "Refusing to run: this seeds fabricated content and is for local development only.",
  );
  process.exit(1);
}

