interface DemoRecord {
  readonly title: string;
  readonly path: string;
  readonly description: string;
  readonly layout: Layout;
  /** `page` for web, `screen` for app. */
  readonly kind: "page" | "screen";
  readonly scheme?: "light" | "dark";
  /** Taxonomy term slugs, matched against the seeded vocabulary by prefix. */
  readonly terms: readonly string[];
}

interface DemoSource {
  readonly name: string;
  readonly company: string;
  readonly product: string;
  readonly description: string;
  readonly module: "web" | "app";
  readonly type: "website" | "app";
  readonly hue: number;
  readonly device: "desktop" | "mobile";
  readonly records: readonly DemoRecord[];
  readonly flows?: readonly {
    readonly title: string;
    readonly goal: string;
    /** Record titles, in order. */
    readonly steps: readonly string[];
  }[];
}

