const env = loadCmsEnv();
const handle = createDatabase({ url: env.DATABASE_URL, applicationName: "uxd-seed-demo" });

const storage = createStorage({
  driver: env.STORAGE_DRIVER,
  localRoot: env.STORAGE_LOCAL_ROOT,
  localPublicBaseUrl: "/media",
  s3:
    env.STORAGE_DRIVER === "s3"
      ? {
          bucket: env.STORAGE_S3_BUCKET!,
          region: env.STORAGE_S3_REGION,
          endpoint: env.STORAGE_S3_ENDPOINT,
          accessKeyId: env.STORAGE_S3_ACCESS_KEY_ID!,
          secretAccessKey: env.STORAGE_S3_SECRET_ACCESS_KEY!,
          forcePathStyle: env.STORAGE_S3_FORCE_PATH_STYLE,
          publicBaseUrl: env.STORAGE_PUBLIC_BASE_URL,
        }
      : undefined,
  logger,
});

/**
 * Resolve term slugs against the seeded vocabulary.
 *
 * The demo records name terms like `pricing` and `data-table`. The seeded
 * vocabulary is the operator's, not this file's, so a name is *looked up*
 * rather than created: a term this file wants and the vocabulary lacks is
 * skipped and reported, not invented. §37 forbids hardcoded taxonomy, and
 * quietly inserting terms to make a demo look complete would be exactly that.
 */
async function resolveTerms(
  db: Database,
  slugs: readonly string[],
): Promise<{ found: Map<string, string>; missing: string[] }> {
  const all = await db
    .select({ id: taxonomyTerms.id, slug: taxonomyTerms.slug, name: taxonomyTerms.name })
    .from(taxonomyTerms)
    .where(eq(taxonomyTerms.status, "active"));

  const found = new Map<string, string>();
  const missing: string[] = [];

  for (const wanted of slugs) {
    // Exact slug, then a slug ending in the wanted word, then a name match.
    const exact = all.find((term) => term.slug === wanted);
    const suffix = exact ?? all.find((term) => term.slug.endsWith(`-${wanted}`));
    const loose =
      suffix ??
      all.find((term) => slugify(term.name) === wanted) ??
      all.find((term) => term.slug.includes(wanted));
    if (loose) found.set(wanted, loose.id);
    else missing.push(wanted);
  }
  return { found, missing };
}

async function main(): Promise<void> {
  const counts = { sources: 0, records: 0, media: 0, deduped: 0, flows: 0, assignments: 0 };

  try {
    const db = handle.db;

    // --- The approver -------------------------------------------------
    //
    // `content_items_approval_attributable` requires a published record to
    // name who approved it. The seed's records are attributed to the admin
    // user, which is honest: a person running the demo seed did approve them,
    // by running it.
    const [approver] = await db
      .select({ id: users.id, email: users.email })
      .from(users)
      .where(and(eq(users.role, "admin"), isNull(users.deletedAt)))
      .limit(1);

    if (!approver) {
      logger.error("No admin user. Run `npm run db:seed` first.");
      process.exitCode = 1;
      return;
    }

    const context = {
      db,
      storage,
      classifier: createHeuristicProvider(),
      logger,
      env,
      requestId: `demo-seed-${Date.now()}`,
      ip: null,
      userAgent: "db-seed-demo",
    };

    const allTermSlugs = [
      ...new Set(LIBRARY.flatMap((source) => source.records.flatMap((record) => record.terms))),
    ];
    const { found: termIds, missing } = await resolveTerms(db, allTermSlugs);
    if (missing.length > 0) {
      logger.warn("Some demo terms are not in the vocabulary and were skipped", {
        missing,
        hint: "Create them on the Taxonomy screen if you want them classified.",
      });
    }

    const now = new Date();

    for (const source of LIBRARY) {
      const domain = `${source.name.toLowerCase()}.example.com`;
      const slug = slugify(source.name);
      const homeUrl = `https://${domain}/`;

      // --- Source -----------------------------------------------------
      const [existingSource] = await db
        .select({ id: sources.id })
        .from(sources)
        .where(and(eq(sources.domain, domain), isNull(sources.deletedAt)))
        .limit(1);

      let sourceId = existingSource?.id;
      if (!sourceId) {
        sourceId = uuidv7();
        await db.insert(sources).values({
          id: sourceId,
          name: source.name,
          slug,
          domain,
          canonicalUrl: homeUrl,
          canonicalUrlHash: urlHash(homeUrl),
          companyName: source.company,
          productName: source.product,
          description: source.description,
          type: source.type,
          module: source.module,
          status: "published",
          health: "healthy",
          platforms: source.module === "app" ? ["ios", "android"] : ["web"],
          primaryDeviceClass: source.device === "mobile" ? "mobile" : "desktop",
          rightsStatus: "reference_use",
          attribution: `${source.company} — shown for reference.`,
          notes: "Fictional product created by the demo seed.",
          firstCapturedAt: now,
          lastCapturedAt: now,
          lastSuccessfulCaptureAt: now,
          robotsStatus: "allowed",
          captureIntervalDays: 30,
          createdBy: approver.id,
        });
        counts.sources += 1;
      }

      // --- The experience record the pages hang off -------------------
      const experienceTitle = source.name;
      const experienceSlug = slugify(`${source.name} ${source.type}`);
      const [existingExperience] = await db
        .select({ id: contentItems.id })
        .from(contentItems)
        .where(eq(contentItems.slug, experienceSlug))
        .limit(1);

      let experienceId = existingExperience?.id;
      if (!experienceId) {
        experienceId = uuidv7();
        await db.insert(contentItems).values({
          id: experienceId,
          sourceId,
          module: source.module,
          kind: source.module === "app" ? "app" : "website",
          title: experienceTitle,
          slug: experienceSlug,
          description: source.description,
          sourceUrl: homeUrl,
          originalCompany: source.company,
          originalProduct: source.product,
          platform: source.module === "app" ? "ios" : "web",
          deviceClass: source.device === "mobile" ? "mobile" : "desktop",
          status: "published",
          rightsStatus: "reference_use",
          attribution: `${source.company} — shown for reference.`,
          capturedAt: now,
          publishedAt: now,
          firstPublishedAt: now,
          approvedAt: now,
          approvedBy: approver.id,
          publishedBy: approver.id,
          reviewedAt: now,
          reviewedBy: approver.id,
          createdBy: approver.id,
        });
        await db.insert(experienceDetails).values({
          contentItemId: experienceId,
          homeUrl,
          pageCount: source.records.filter((r) => r.kind === "page").length,
          screenCount: source.records.filter((r) => r.kind === "screen").length,
          flowCount: source.flows?.length ?? 0,
        });
        counts.records += 1;
      }

      // --- Records ----------------------------------------------------
      const recordIds = new Map<string, string>();

      for (const record of source.records) {
        const url = `https://${domain}${record.path}`;
        const normalized = normalizeUrl(url);
        const hash = urlHash(url);
        if (normalized === null || hash === null) {
          logger.warn("Skipping a demo record whose URL did not normalise", { url });
          continue;
        }

        const recordSlug = slugify(`${source.name} ${record.title}`);
        const [existing] = await db
          .select({ id: contentItems.id })
          .from(contentItems)
          .where(eq(contentItems.slug, recordSlug))
          .limit(1);

        let contentId = existing?.id;
        if (!contentId) {
          contentId = uuidv7();
          await db.insert(contentItems).values({
            id: contentId,
            sourceId,
            experienceId,
            parentId: experienceId,
            module: source.module,
            kind: record.kind,
            title: record.title,
            slug: recordSlug,
            description: record.description,
            sourceUrl: url,
            originalCompany: source.company,
            originalProduct: source.product,
            platform: source.module === "app" ? "ios" : "web",
            deviceClass: source.device === "mobile" ? "mobile" : "desktop",
            status: "published",
            rightsStatus: "reference_use",
            attribution: `${source.company} — shown for reference.`,
            capturedAt: now,
            publishedAt: now,
            firstPublishedAt: now,
            approvedAt: now,
            approvedBy: approver.id,
            publishedBy: approver.id,
            reviewedAt: now,
            reviewedBy: approver.id,
            createdBy: approver.id,
          });

          if (record.kind === "page") {
            await db.insert(pageDetails).values({
              contentItemId: contentId,
              url,
              normalizedUrl: normalized,
              normalizedUrlHash: hash,
              httpStatus: 200,
              pageTitle: `${record.title} · ${source.product}`,
              metaDescription: record.description,
              h1: record.title,
              langAttr: "en",
              wordCount: 240 + record.description.length,
              pageWidth: 1440,
              pageHeight: 900,
              viewportWidth: 1440,
              viewportHeight: 900,
            });
          } else {
            await db.insert(screenDetails).values({
              contentItemId: contentId,
              screenName: record.title,
              deepLink: url,
              appVersion: "1.0.0",
              osVersion: "iOS 18",
              acquisition: "Generated by the demo seed",
              viewportWidth: 390,
              viewportHeight: 844,
            });
          }
          counts.records += 1;
        }
        recordIds.set(record.title, contentId);

        // --- Screenshots, through the real media pipeline ------------
        const [alreadyAttached] = await db
          .select({ mediaId: mediaUsages.mediaId })
          .from(mediaUsages)
          .where(eq(mediaUsages.contentItemId, contentId))
          .limit(1);

        if (!alreadyAttached) {
          const shot = await renderScreenshot({
            title: record.title,
            product: source.product,
            layout: record.layout,
            hue: source.hue,
            device: source.device,
            scheme: record.scheme,
          });

          const result = await ingestMedia(context, {
            bytes: shot.bytes,
            originalFilename: `${recordSlug}.png`,
            altText: `${record.title} screen from ${source.product}`,
            caption: record.description,
            title: `${source.product} — ${record.title}`,
            uploadedBy: approver.id,
            provenance: {
              sourceUrl: url,
              originDomain: domain,
              sourceId,
              parentContentId: contentId,
              // `import`, not `browser_render`. No browser rendered these —
              // they are generated PNGs — and claiming otherwise would put a
              // false provenance record in the one place the system's value
              // depends on being true. The integrity audit
              // (`scripts/audit-integrity.mjs`) is what caught it: it asked
              // which capture row produced each browser-rendered asset and
              // found 22 of 24 had none, because none existed.
              captureMethod: "import",
              uploadSource: "import",
              capturedAt: now,
              viewportWidth: shot.width,
              viewportHeight: shot.height,
              deviceScaleFactor: 1,
              deviceProfile: source.device === "mobile" ? "mobile-390" : "desktop-1440",
              deviceClass: source.device === "mobile" ? "mobile" : "desktop",
              screenshotScope: "full_page",
            },
          });

          if (result.deduplicated) counts.deduped += 1;
          else counts.media += 1;

          await attachMedia(db, {
            mediaId: result.mediaId,
            contentItemId: contentId,
            role: source.device === "mobile" ? "screenshot_mobile" : "screenshot_desktop",
            position: 0,
            createdBy: approver.id,
          });
          await attachMedia(db, {
            mediaId: result.mediaId,
            contentItemId: contentId,
            role: "primary",
            position: 0,
            createdBy: approver.id,
          });
          await db
            .update(contentItems)
            .set({ primaryMediaId: result.mediaId, updatedAt: new Date() })
            .where(eq(contentItems.id, contentId));
        }

        // --- URL registry -------------------------------------------
        //
        // `intakeCapture` maintains this on the real path; a seed that writes
        // content rows directly bypasses it, and the consequence is not
        // cosmetic: `validateUrlBatch` checks the registry to decide whether a
        // URL has been seen before, so a seeded URL would come back `valid`
        // and be captured again as though it were new. Registering here keeps
        // duplicate detection honest about the whole dataset.
        if (record.kind === "page") {
          await db
            .insert(urlRegistry)
            .values({
              normalizedUrlHash: hash,
              normalizedUrl: normalized,
              host: domain,
              registrableDomain: registrableDomain(domain) ?? domain,
              sourceId,
              contentItemId: contentId,
              lastCapturedAt: now,
              captureCount: 1,
              lastHttpStatus: 200,
            })
            .onConflictDoNothing({ target: urlRegistry.normalizedUrlHash });
        }

        // --- Classification, human-confirmed so it is public --------
        for (const wanted of record.terms) {
          const termId = termIds.get(wanted);
          if (!termId) continue;
          const [present] = await db
            .select({ id: taxonomyAssignments.id })
            .from(taxonomyAssignments)
            .where(
              and(
                eq(taxonomyAssignments.termId, termId),
                eq(taxonomyAssignments.contentItemId, contentId),
              ),
            )
            .limit(1);
          if (present) continue;

          await db.insert(taxonomyAssignments).values({
            id: uuidv7(),
            termId,
            target: "content",
            contentItemId: contentId,
            // `human_added` is the strongest provenance there is, and it is
            // the honest one: a person chose these, in this file.
            origin: "human_added",
            reviewStatus: "accepted",
            reviewedBy: approver.id,
            reviewedAt: now,
            createdBy: approver.id,
          });
          counts.assignments += 1;
        }
      }

      // --- Flows ------------------------------------------------------
      for (const flow of source.flows ?? []) {
        const flowSlug = slugify(`${source.name} ${flow.title}`);
        const [existingFlow] = await db
          .select({ id: contentItems.id })
          .from(contentItems)
          .where(eq(contentItems.slug, flowSlug))
          .limit(1);
        if (existingFlow) continue;

        const stepIds = flow.steps
          .map((title) => ({ title, id: recordIds.get(title) }))
          .filter((step): step is { title: string; id: string } => Boolean(step.id));
        if (stepIds.length === 0) continue;

        const flowId = uuidv7();
        await db.insert(contentItems).values({
          id: flowId,
          sourceId,
          experienceId,
          module: source.module,
          kind: "flow",
          title: flow.title,
          slug: flowSlug,
          description: flow.goal,
          sourceUrl: homeUrl,
          originalCompany: source.company,
          originalProduct: source.product,
          platform: source.module === "app" ? "ios" : "web",
          deviceClass: source.device === "mobile" ? "mobile" : "desktop",
          status: "published",
          rightsStatus: "reference_use",
          attribution: `${source.company} — shown for reference.`,
          capturedAt: now,
          publishedAt: now,
          firstPublishedAt: now,
          approvedAt: now,
          approvedBy: approver.id,
          publishedBy: approver.id,
          createdBy: approver.id,
          // A flow's primary image is its first step's, so a flow card in a
          // grid is not a blank tile.
          primaryMediaId: (
            await db
              .select({ id: contentItems.primaryMediaId })
              .from(contentItems)
              .where(eq(contentItems.id, stepIds[0]!.id))
              .limit(1)
          )[0]?.id,
        });

        await db.insert(flowDetails).values({
          contentItemId: flowId,
          goal: flow.goal,
          stepCount: stepIds.length,
          entryContentId: stepIds[0]!.id,
          exitContentId: stepIds[stepIds.length - 1]!.id,
          observations:
            "Assembled by the demo seed from screens already in the library, which is how a real flow is built too.",
        });

        await db.insert(flowSteps).values(
          stepIds.map((step, index) => ({
            id: uuidv7(),
            flowId,
            contentItemId: step.id,
            position: index,
            label: step.title,
          })),
        );
        counts.flows += 1;
      }

      // --- The experience record's cover -----------------------------
      //
      // A website or app record has no capture of its own — it is the thing the
      // pages belong to — so without this it appears in a grid as a blank tile.
      // Borrowing its first page's screenshot is how a real library shows a
      // product, and it costs no extra file: the same media row is reused.
      const [experienceCover] = await db
        .select({ id: contentItems.primaryMediaId })
        .from(contentItems)
        .where(and(eq(contentItems.id, experienceId), isNull(contentItems.primaryMediaId)))
        .limit(1);

      if (experienceCover !== undefined) {
        const firstRecordId = [...recordIds.values()][0];
        const [first] = firstRecordId
          ? await db
              .select({ id: contentItems.primaryMediaId })
              .from(contentItems)
              .where(eq(contentItems.id, firstRecordId))
              .limit(1)
          : [];

        if (first?.id) {
          await attachMedia(db, {
            mediaId: first.id,
            contentItemId: experienceId,
            role: "cover",
            createdBy: approver.id,
          });
          await db
            .update(contentItems)
            .set({ primaryMediaId: first.id, updatedAt: new Date() })
            .where(eq(contentItems.id, experienceId));
        }
      }

      logger.info(`Seeded ${source.name}`, {
        records: source.records.length,
        flows: source.flows?.length ?? 0,
      });
    }

    // --- Collections ---------------------------------------------------
    for (const collection of DEMO_COLLECTIONS) {
      const [existing] = await db
        .select({ id: collections.id })
        .from(collections)
        .where(eq(collections.slug, collection.slug))
        .limit(1);

      let collectionId = existing?.id;
      if (!collectionId) {
        collectionId = uuidv7();
        await db.insert(collections).values({
          id: collectionId,
          name: collection.name,
          slug: collection.slug,
          description: collection.description,
          visibility: collection.visibility,
          status: "active",
          module: "web",
          publishedAt: now,
          curatedBy: approver.id,
          createdBy: approver.id,
        });
      }

      const members = await db
        .select({ id: contentItems.id, title: contentItems.title })
        .from(contentItems)
        .where(
          and(
            inArray(contentItems.title, [...collection.match]),
            eq(contentItems.status, "published"),
            isNull(contentItems.deletedAt),
          ),
        );

      const [countedRow] = await db
        .select({ n: sql<number>`count(*)::int` })
        .from(collectionItems)
        .where(eq(collectionItems.collectionId, collectionId));

      if ((countedRow?.n ?? 0) === 0 && members.length > 0) {
        await db.insert(collectionItems).values(
          members.map((member, index) => ({
            id: uuidv7(),
            collectionId: collectionId!,
            contentItemId: member.id,
            position: index,
            createdBy: approver.id,
          })),
        );
      }

      await db
        .update(collections)
        .set({
          itemCount: sql`(
            select count(*)::int from ${collectionItems}
            where collection_id = ${collections}.id
          )`,
          updatedAt: new Date(),
        })
        .where(eq(collections.id, collectionId));
    }

    // --- Counters ------------------------------------------------------
    //
    // Recomputed rather than incremented, for the same reason the capture
    // intake does it: deduplication and re-seeding both break a delta.
    await db.update(sources).set({
      contentCount: sql`(
        select count(*)::int from ${contentItems}
        where source_id = ${sources}.id and deleted_at is null
      )`,
      mediaCount: sql`(
        select count(distinct mu.media_id)::int
        from ${mediaUsages} mu
        join ${contentItems} ci on ci.id = mu.content_item_id
        where ci.source_id = ${sources}.id and ci.deleted_at is null
      )`,
    });

    await db.update(taxonomyTerms).set({
      usageCount: sql`(
        select count(*)::int from ${taxonomyAssignments} ta
        where ta.term_id = ${taxonomyTerms}.id and ta.review_status <> 'rejected'
      )`,
    });

    logger.info("Demo seed complete", counts);
    logger.info(
      "Everything is published, so the public site at http://localhost:3001 has content to show.",
    );
  } catch (error) {
    logger.error("Demo seed failed", { error });
    process.exitCode = 1;
  } finally {
    await handle.close();
  }
}

await main();
